#!/usr/bin/env python3
"""
htmlq - A command-line utility for querying HTML documents with CSS selectors
Pure Python implementation using only standard library
"""

import sys
import argparse
import re
from html.parser import HTMLParser
from urllib.parse import urljoin, urlparse
from io import StringIO

class HTMLElement:
    """Represents an HTML element"""
    def __init__(self, tag, attrs=None, parent=None):
        self.tag = tag.lower()
        self.attrs = attrs or []
        self.parent = parent
        self.children = []
        self.text_content = []

    def add_child(self, child):
        child.parent = self
        self.children.append(child)

    def add_text(self, text):
        self.text_content.append(text)

    def get_attribute(self, name):
        for attr_name, attr_value in self.attrs:
            if attr_name.lower() == name.lower():
                return attr_value
        return None

    def set_attribute(self, name, value):
        for i, (attr_name, attr_value) in enumerate(self.attrs):
            if attr_name.lower() == name.lower():
                self.attrs[i] = (attr_name, value)
                return
        self.attrs.append((name, value))

    def has_class(self, class_name):
        classes = self.get_attribute('class')
        if not classes:
            return False
        return class_name in classes.split()

    def get_all_text(self):
        """Get all text content recursively"""
        result = []
        for text in self.text_content:
            result.append(text)
        for child in self.children:
            result.append(child.get_all_text())
        return ''.join(result)

    def matches_selector(self, selector, root=None):
        """Check if this element matches a CSS selector"""
        if root is None:
            root = self

        selector = selector.strip()

        # Handle descendant selector
        if ' ' in selector and not selector.startswith('::'):
            parts = selector.split(None, 1)
            ancestor_selector = parts[0]
            child_selector = parts[1]

            # Check if any ancestor matches
            current = self
            while current:
                if current.matches_selector(ancestor_selector, root):
                    # Now check if we can find a descendant matching child_selector
                    if self.matches_selector(child_selector, root):
                        return True
                current = current.parent
            return False

        # Handle child combinator
        if '>' in selector:
            parts = selector.split('>')
            parent_sel = parts[0].strip()
            child_sel = parts[1].strip()
            if self.parent and self.parent.matches_selector(parent_sel, root):
                return self.matches_selector(child_sel, root)
            return False

        # Remove leading/trailing spaces
        selector = selector.strip()

        # Universal selector
        if selector == '*':
            return True

        # ID selector
        if selector.startswith('#'):
            id_val = selector[1:]
            return self.get_attribute('id') == id_val

        # Class selector
        if selector.startswith('.'):
            class_name = selector[1:]
            return self.has_class(class_name)

        # Attribute selector
        if '[' in selector and ']' in selector:
            match = re.match(r'([^\[]*)\[([^\]]+)\]', selector)
            if match:
                tag_part = match.group(1).strip() or None
                attr_part = match.group(2)

                if tag_part and tag_part != self.tag:
                    return False

                # Handle [attr], [attr="value"], [attr~="value"], [attr|="value"], [attr^="value"], [attr$="value"], [attr*="value"]
                if '=' in attr_part:
                    attr_match = re.match(r'([^=]+)([\~\|\^\$\*]?)=(["\']?)([^"\']*)\3', attr_part)
                    if attr_match:
                        attr_name = attr_match.group(1).strip()
                        op = attr_match.group(2)
                        attr_value = attr_match.group(4)
                        actual = self.get_attribute(attr_name)
                        if actual is None:
                            return False
                        if op == '':
                            return actual == attr_value
                        elif op == '~':
                            return attr_value in actual.split()
                        elif op == '|':
                            return actual == attr_value or actual.startswith(attr_value + '-')
                        elif op == '^':
                            return actual.startswith(attr_value)
                        elif op == '$':
                            return actual.endswith(attr_value)
                        elif op == '*':
                            return attr_value in actual
                else:
                    attr_name = attr_part.strip()
                    return self.get_attribute(attr_name) is not None
            return False

        # Type selector with class
        if '.' in selector:
            parts = selector.split('.')
            tag = parts[0] or None
            classes = parts[1:]

            if tag and tag != self.tag:
                return False

            for cls in classes:
                if not self.has_class(cls):
                    return False
            return True

        # Type selector with ID
        if '#' in selector:
            parts = selector.split('#')
            tag = parts[0] or None
            id_val = parts[1]

            if tag and tag != self.tag:
                return False

            return self.get_attribute('id') == id_val

        # Simple type selector
        return self.tag == selector

    def serialize(self, pretty=False, indent=0):
        """Serialize to HTML"""
        result = []
        indent_str = '  ' * indent if pretty else ''

        # Opening tag
        result.append(indent_str + '<' + self.tag)
        for attr_name, attr_value in self.attrs:
            if attr_value is not None:
                # Escape attribute value
                attr_value = attr_value.replace('&', '&amp;').replace('<', '&lt;').replace('>', '&gt;').replace('"', '&quot;')
                result.append(f' {attr_name}="{attr_value}"')
            else:
                result.append(f' {attr_name}')
        result.append('>')
        if pretty:
            result.append('\n')

        # Content
        for text in self.text_content:
            if pretty:
                lines = text.split('\n')
                for line in lines:
                    if line.strip():
                        result.append(indent_str + '  ' + line + '\n')
                    elif line:
                        result.append('\n')
            else:
                result.append(text)

        for child in self.children:
            result.append(child.serialize(pretty, indent + 1 if pretty else 0))

        # Closing tag
        if pretty and (self.text_content or self.children):
            result.append(indent_str)
        result.append('</' + self.tag + '>')
        if pretty:
            result.append('\n')

        return ''.join(result)

    def find_all(self, selector):
        """Find all elements matching selector"""
        results = []

        # Check self
        if self.matches_selector(selector):
            results.append(self)

        # Check children recursively
        for child in self.children:
            results.extend(child.find_all(selector))

        return results


class SimpleHTMLParser(HTMLParser):
    """Simple HTML parser that builds a tree"""
    def __init__(self):
        super().__init__()
        self.root = None
        self.current = None
        self.void_elements = {'area', 'base', 'br', 'col', 'embed', 'hr', 'img', 'input', 
                             'link', 'meta', 'param', 'source', 'track', 'wbr'}

    def handle_starttag(self, tag, attrs):
        element = HTMLElement(tag, attrs)
        if self.root is None:
            self.root = element
            self.current = element
        else:
            self.current.add_child(element)
            if tag not in self.void_elements:
                self.current = element

    def handle_endtag(self, tag):
        if self.current and self.current.tag == tag.lower():
            if self.current.parent:
                self.current = self.current.parent

    def handle_data(self, data):
        if self.current:
            self.current.add_text(data)

    def handle_entityref(self, name):
        # Handle named entities like &nbsp;
        entities = {
            'lt': '<', 'gt': '>', 'amp': '&', 'quot': '"', 'apos': "'",
            'nbsp': '\u00a0',
        }
        if name in entities:
            if self.current:
                self.current.add_text(entities[name])

    def handle_charref(self, name):
        # Handle numeric entities like &#123;
        if name.startswith('x'):
            char = chr(int(name[1:], 16))
        else:
            char = chr(int(name))
        if self.current:
            self.current.add_text(char)


def parse_html(html_string):
    """Parse HTML string and return root element"""
    parser = SimpleHTMLParser()
    parser.feed(html_string)
    return parser.root


def process_html(root, selector, text_only=False, attribute=None, ignore_whitespace=False,
                remove_nodes=None, base_url=None, detect_base=False):
    """Process HTML and return matching elements"""

    if remove_nodes:
        # Remove specified nodes
        for selector_to_remove in remove_nodes:
            elements = root.find_all(selector_to_remove)
            for elem in elements:
                if elem.parent:
                    elem.parent.children.remove(elem)

    # Detect base URL if needed
    if detect_base:
        base_elements = root.find_all('base')
        if base_elements:
            href = base_elements[0].get_attribute('href')
            if href:
                base_url = href

    # Find matching elements
    matches = root.find_all(selector)

    results = []
    for element in matches:
        if attribute:
            # Return attribute value
            val = element.get_attribute(attribute)
            if val is not None:
                # Resolve relative URLs if base URL is set
                if attribute.lower() == 'href' and base_url:
                    val = urljoin(base_url, val)
                results.append(val)
        elif text_only:
            # Return text content
            text = element.get_all_text()
            if ignore_whitespace:
                # Split by lines and filter empty
                lines = [line for line in text.split('\n') if line.strip()]
                text = '\n'.join(lines)
            results.append(text)
        else:
            # Return serialized element
            results.append(element.serialize())

    return results


def main():
    parser = argparse.ArgumentParser(
        prog='htmlq',
        description='Runs CSS selectors on HTML'
    )

    parser.add_argument('--version', '-V', action='version', version='htmlq 0.4.0')
    parser.add_argument('--text', '-t', action='store_true',
                       help='Output only the contents of text nodes inside selected elements')
    parser.add_argument('--attribute', '-a', dest='attribute',
                       help='Only return this attribute (if present) from selected elements')
    parser.add_argument('--pretty', '-p', action='store_true',
                       help='Pretty-print the serialised output')
    parser.add_argument('--filename', '-f', dest='filename',
                       help='The input file. Defaults to stdin')
    parser.add_argument('--output', '-o', dest='output',
                       help='The output file. Defaults to stdout')
    parser.add_argument('--ignore-whitespace', '-w', action='store_true',
                       help='When printing text nodes, ignore those that consist entirely of whitespace')
    parser.add_argument('--base', '-b', dest='base',
                       help='Use this URL as the base for links')
    parser.add_argument('--detect-base', '-B', action='store_true',
                       help='Try to detect the base URL from the <base> tag in the document')
    parser.add_argument('--remove-nodes', '-r', dest='remove_nodes', nargs='*',
                       help='Remove nodes matching this expression before output')
    parser.add_argument('selector', nargs='*', default=['html'],
                       help='The CSS expression to select')

    args = parser.parse_args()

    # Read input
    if args.filename:
        with open(args.filename, 'r') as f:
            html_content = f.read()
    else:
        html_content = sys.stdin.read()

    # Parse HTML
    root = parse_html(html_content)

    if not root:
        return

    # Process each selector
    all_results = []
    for selector in args.selector:
        results = process_html(
            root,
            selector,
            text_only=args.text,
            attribute=args.attribute,
            ignore_whitespace=args.ignore_whitespace,
            remove_nodes=args.remove_nodes if args.remove_nodes else None,
            base_url=args.base,
            detect_base=args.detect_base
        )
        all_results.extend(results)

    # Write output
    output_content = '\n'.join(all_results)
    if args.output:
        with open(args.output, 'w') as f:
            f.write(output_content)
            if output_content:
                f.write('\n')
    else:
        print(output_content)


if __name__ == '__main__':
    main()
