#!/usr/bin/env python3
"""
htmlq - A command-line utility for querying HTML documents with CSS selectors
Pure Python implementation using only standard library
"""

import sys
import argparse
import re
from html.parser import HTMLParser
from urllib.parse import urljoin


class Element:
    """Represents an HTML element in the DOM"""
    def __init__(self, tag, attrs=None):
        self.tag = tag.lower()
        self.attrs = dict(attrs) if attrs else {}
        self.parent = None
        self.children = []
        self.text_parts = []  # List of (is_text, content) tuples

    def add_text(self, text):
        """Add text content"""
        self.text_parts.append((True, text))

    def add_child(self, child):
        """Add child element"""
        child.parent = self
        self.children.append(child)
        self.text_parts.append((False, child))

    def get_text(self, recursive=True):
        """Get all text content"""
        result = []
        for is_text, content in self.text_parts:
            if is_text:
                result.append(content)
            elif recursive:
                result.append(content.get_text(recursive=True))
        return ''.join(result)

    def get_attr(self, name):
        """Get attribute value"""
        return self.attrs.get(name.lower())

    def has_class(self, cls):
        """Check if element has class"""
        classes = self.attrs.get('class', '')
        return cls in classes.split()

    def to_html(self):
        """Serialize to HTML"""
        result = ['<' + self.tag]
        for k, v in self.attrs.items():
            if v is not None:
                result.append(f' {k}="{self._escape_attr(v)}"')
            else:
                result.append(f' {k}')
        result.append('>')

        for is_text, content in self.text_parts:
            if is_text:
                result.append(self._escape_html(content))
            else:
                result.append(content.to_html())

        result.append(f'</{self.tag}>')
        return ''.join(result)

    @staticmethod
    def _escape_html(text):
        return (text.replace('&', '&amp;')
                    .replace('<', '&lt;')
                    .replace('>', '&gt;'))

    @staticmethod
    def _escape_attr(text):
        return (text.replace('&', '&amp;')
                    .replace('<', '&lt;')
                    .replace('>', '&gt;')
                    .replace('"', '&quot;'))


class HTMLBuilder(HTMLParser):
    """Parse HTML and build a DOM tree"""
    VOID_ELEMENTS = {'area', 'base', 'br', 'col', 'embed', 'hr', 'img', 'input',
                     'link', 'meta', 'param', 'source', 'track', 'wbr'}

    def __init__(self):
        super().__init__()
        self.root = None
        self.stack = []
        self.entities = {
            'nbsp': '\u00a0', 'lt': '<', 'gt': '>', 'amp': '&', 'quot': '"'
        }

    def handle_starttag(self, tag, attrs):
        elem = Element(tag, attrs)
        if not self.root:
            self.root = elem
            if tag.lower() not in self.VOID_ELEMENTS:
                self.stack.append(elem)
        else:
            parent = self.stack[-1] if self.stack else self.root
            parent.add_child(elem)
            if tag.lower() not in self.VOID_ELEMENTS:
                self.stack.append(elem)

    def handle_endtag(self, tag):
        if self.stack and self.stack[-1].tag == tag.lower():
            self.stack.pop()

    def handle_data(self, data):
        if self.root:
            elem = self.stack[-1] if self.stack else self.root
            elem.add_text(data)

    def handle_entityref(self, name):
        if self.root:
            elem = self.stack[-1] if self.stack else self.root
            elem.add_text(self.entities.get(name, f'&{name};'))

    def handle_charref(self, name):
