        if ' ' in selector and not any(c in selector.split()[0] for c in '[]'):
            parts = selector.split(None, 1)
            ancestor_sel = parts[0]
            child_sel = parts[1]
            # Check if any ancestor matches ancestor_sel
            current = element
            while current:
                if CSSMatcher.match(current, child_sel):
                    parent = current.parent
                    while parent:
                        if CSSMatcher.match(parent, ancestor_sel):
                            return True
                        parent = parent.parent
                current = current.parent
            return False

        # Child combinator (>)
        if '>' in selector:
            parts = selector.split('>')
            parent_sel = parts[0].strip()
            child_sel = parts[1].strip()
            if element.parent and CSSMatcher.match(element, child_sel):
                return CSSMatcher.match(element.parent, parent_sel)
            return False

        # Universal selector
        if selector == '*':
            return True

        # ID selector
        if selector.startswith('#'):
            return element.get_attr('id') == selector[1:]

        # Class selector
        if selector.startswith('.'):
            return element.has_class(selector[1:])

        # Type.class
        if '.' in selector:
            parts = selector.split('.', 1)
            tag = parts[0] or None
            classes = parts[1].split('.')
            if tag and element.tag != tag:
                return False
            return all(element.has_class(c) for c in classes)

        # Type#id
        if '#' in selector:
            parts = selector.split('#', 1)
            tag = parts[0] or None
            id_val = parts[1]
            if tag and element.tag != tag:
                return False
            return element.get_attr('id') == id_val

        # Attribute selector
        if '[' in selector and ']' in selector:
            return CSSMatcher.match_attr(element, selector)

        # Simple tag selector
        return element.tag == selector

    @staticmethod
    def match_attr(element, selector):
