        match = re.match(r'^([^\[]*)\[([^\]]*)\]', selector)
        if not match:
            return False

        tag_part = match.group(1).strip()
        attr_part = match.group(2)

        if tag_part and element.tag != tag_part:
            return False

        if '=' not in attr_part:
            # [attr]
            return element.get_attr(attr_part) is not None

        # [attr=value], [attr~=value], etc.
        m = re.match(r'([^=]+)([\~\|\^\$\*]?)="([^"]*)"', attr_part)
        if not m:
            m = re.match(r"([^=]+)([\~\|\^\$\*]?)='([^']*)'", attr_part)
        if not m:
            m = re.match(r'([^=]+)([\~\|\^\$\*]?)=([^\s\]]*)', attr_part)

        if not m:
            return False

        attr_name = m.group(1).strip()
        operator = m.group(2) or '='
        attr_value = m.group(3)

        actual = element.get_attr(attr_name)
        if actual is None:
            return False

        if operator == '=':
            return actual == attr_value
        elif operator == '~':
            return attr_value in actual.split()
        elif operator == '|':
            return actual == attr_value or actual.startswith(attr_value + '-')
        elif operator == '^':
            return actual.startswith(attr_value)
        elif operator == '$':
            return actual.endswith(attr_value)
        elif operator == '*':
            return attr_value in actual

        return False

    @staticmethod
    def find_all(root, selector):
        """Find all elements matching selector"""
        results = []

        def traverse(elem):
            if CSSMatcher.match(elem, selector):
                results.append(elem)
            for child in elem.children:
                traverse(child)

        traverse(root)
        return results


