        self.text_parts.append((True, text))

    def add_child(self, child):
        """Add child element"""
        child.parent = self
        self.children.append(child)
        self.text_parts.append((False, child))

    def get_text(self, recursive=True, ignore_whitespace=False):
        """Get all text content"""
        result = []
        for is_text, content in self.text_parts:
            if is_text:
                if ignore_whitespace:
                    # Keep lines that have non-whitespace content, strip leading/trailing whitespace from line
                    lines = content.split('\n')
                    kept_lines = []
                    for line in lines:
                        if line.strip():
                            kept_lines.append(line.strip())
                    if kept_lines:
